#include <bits/stdc++.h>
using namespace std;

class HopcroftKarp {
    static constexpr int INF = numeric_limits<int>::max();

    int vertices;
    int shortest;
    const vector<int>& offset;
    const vector<int>& adjacent;
    vector<int> mate;
    vector<int> distance;
    vector<int> nextEdge;

    bool bfs() {
        queue<int> q;
        fill(distance.begin(), distance.end(), -1);
        shortest = INF;

        for (int u = 0; u < vertices; ++u) {
            if (((u / columns) + (u % columns)) % 2 == 0 &&
                mate[u] == -1) {
                distance[u] = 0;
                q.push(u);
            }
        }

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            if (distance[u] >= shortest)
                continue;

            for (int i = offset[u]; i < offset[u + 1]; ++i) {
                int v = adjacent[i];
                int next = mate[v];

                if (next == -1) {
                    shortest = distance[u];
                } else if (distance[next] == -1) {
                    distance[next] = distance[u] + 1;
                    q.push(next);
                }
            }
        }

        return shortest != INF;
    }

    bool dfs(int u) {
        for (int& i = nextEdge[u]; i < offset[u + 1]; ++i) {
            int v = adjacent[i];
            int next = mate[v];

            if (next == -1) {
                if (distance[u] != shortest)
                    continue;
            } else {
                if (distance[next] != distance[u] + 1 || !dfs(next))
                    continue;
            }

            mate[u] = v;
            mate[v] = u;
            return true;
        }

        distance[u] = -1;
        return false;
    }

public:
    static int columns;

    HopcroftKarp(int vertexCount, const vector<int>& offsets,
                 const vector<int>& edges)
        : vertices(vertexCount),
          offset(offsets),
          adjacent(edges),
          mate(vertexCount, -1),
          distance(vertexCount),
          nextEdge(vertexCount) {}

    int maximumMatching() {
        int matching = 0;

        while (bfs()) {
            for (int u = 0; u < vertices; ++u)
                nextEdge[u] = offset[u];

            for (int u = 0; u < vertices; ++u) {
                if (((u / columns) + (u % columns)) % 2 == 0 &&
                    mate[u] == -1 && dfs(u)) {
                    ++matching;
                }
            }
        }

        return matching;
    }
};

int HopcroftKarp::columns = 0;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    const int moves[8][2] = {
        {-2, -1}, {-2, 1}, {-1, -2}, {-1, 2},
        {1, -2},  {1, 2},  {2, -1},  {2, 1}
    };

    int cells = n * m;
    vector<int> offset(cells + 1, 0);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            int u = i * m + j;
            int degree = 0;

            if ((i + j) % 2 == 0) {
                for (const auto& move : moves) {
                    int ni = i + move[0];
                    int nj = j + move[1];
                    if (0 <= ni && ni < n && 0 <= nj && nj < m)
                        ++degree;
                }
            }

            offset[u + 1] = offset[u] + degree;
        }
    }

    vector<int> adjacent(offset[cells]);
    vector<int> position = offset;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if ((i + j) % 2 != 0)
                continue;

            int u = i * m + j;
            for (const auto& move : moves) {
                int ni = i + move[0];
                int nj = j + move[1];

                if (0 <= ni && ni < n && 0 <= nj && nj < m)
                    adjacent[position[u]++] = ni * m + nj;
            }
        }
    }

    HopcroftKarp::columns = m;
    HopcroftKarp matcher(cells, offset, adjacent);

    cout << static_cast<long long>(cells) - matcher.maximumMatching() << '\n';
    return 0;
}

